[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:HowTo ;
                    schema1:step [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType ns2:LabProcess ;
                            schema1:description "Fifty milligrams of rock powder digested in a sealed PTFE-lined stainless steel bomb, taken up and made up to 50 ml with ultra-pure water and Rh internal standard — clean-room conditions (§3.3); for As and Te, 4.80 ml of sample solution plus 0.20 ml ethanol" ;
                            schema1:name "Sample preparation" ;
                            schema1:position 1 ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalProperty <https://ada.astromat.org/metadata/parameter/module/SolutionIntroduction/digestionDurationDefault>,
                                <https://ada.astromat.org/metadata/parameter/module/SolutionIntroduction/digestionTemperatureDefault>,
                                <https://ada.astromat.org/metadata/parameter/module/SolutionIntroduction/digestionVesselType> ;
                            schema1:additionalType ns2:LabProcess ;
                            schema1:description "bomb attack (1 ml HNO3 + 1 ml HF, 190 °C for 48 h, then evaporated to incipient dryness and twice taken to dryness with 1 ml HNO3); re-dissolution (1.5 ml HNO3 + 2.5 ml ultra-pure water, capped, 150 °C overnight) — §3.3 numbers five operations; the evaporations carry no attack of their own" ;
                            schema1:name "Sample digestion" ;
                            schema1:position 4 ;
                            ns2:reagent [ a schema1:DefinedTerm ;
                                    schema1:name "bomb attack: HNO3 + HF; re-dissolution: HNO3 — §3.3" ] ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType ns2:LabProcess ;
                            schema1:description "no value available: schema:description" ;
                            schema1:name "Data acquisition" ;
                            schema1:position 2 ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalProperty <https://ada.astromat.org/metadata/parameter/module/ICPMS/isotopeDilutionDataReductionMethod> ;
                            schema1:additionalType ns2:LabProcess ;
                            schema1:name "Data processing" ;
                            schema1:position 3 ;
                            ns1:detectionLimitMethod "no value available: ada:detectionLimitMethod" ] ] ;
            sh:resultMessage "A HowTo methodology must have a schema:name" ;
            sh:resultPath schema1:name ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "A HowTo methodology must have a schema:name" ;
                    sh:minCount 1 ;
                    sh:path schema1:name ;
                    sh:severity sh:Violation ] ] .

